const latestFreshnessSeq = Math.max(latestAnchor.seq, threadParentAnchor?.seq ?? 0);
const latestFreshnessMessageId = latestAnchor.seq > 0 && latestAnchor.seq >= (threadParentAnchor?.seq ?? 0)
  ? latestAnchor.messageId
  : (threadParentAnchor?.messageId ?? latestAnchor.messageId);
const fallbackBoundarySeq = threadParentAnchor?.seq ?? 0;
const attestedBoundarySeq = Math.min(
  hasClientSeenBoundary ? clientSeenUpToSeq : fallbackBoundarySeq,
  latestFreshnessSeq,
);

export type AgentInboxFreshnessDecision = {
  action: AgentInboxStateMachineAction;
  decision: "local_hold" | "syncing_hold" | "forward" | "bypass";
  freshnessContextMode?: "inline" | "withheld";
  producerFactId?: string;
  target?: string;
  inboxTrustState: "trusted" | "untrusted";
  reason: string;
  pendingCount?: number;
  pendingMaxSeq?: number;
  modelSeenSeq?: number;
  heldMessageCount?: number;
  omittedMessageCount?: number;
};

const pending = coordinator?.getAllPendingMessages?.() ?? [];
const rows = projectAgentInboxSnapshot(pending);
const appItems = registration.appInbox?.list() ?? [];
const acknowledgedAppSources = registration.appInbox?.listAcknowledgedSources() ?? [];
const items = [
  ...rows.map((row) => ({ source: "message_target" as const, row })),
  ...appItems,
];

const agentContext = ctx.loadAgentContext();
const result = await drainInbox(
  agentContext,
  { block: false },
  ctx.createApiClient(agentContext),
);

if (readOpts.around === undefined) {
  const rows = res.data.messages ?? [];
  let maxSeq = 0;
  for (const row of rows) {
    if (typeof row.seq === "number" && Number.isFinite(row.seq) && row.seq > maxSeq) maxSeq = row.seq;
  }
  recordConsumedRead(agentContext.agentId, readOpts.channel, maxSeq > 0 ? maxSeq : undefined);
}

const plan = planAgentInboxSideEffect({
  agentId: registration.agentId,
  action,
  target,
  continueAnyway,
  freshnessContextMode,
  existingSeenUpToSeq: existingBoundary,
  modelSeenSeq: coordinator.getBoundary(target),
  pendingMessages: pending,
  recentMessages: recent,
  isMessageModelSeen: (messageInput) => coordinator.isMessageModelSeen?.(messageInput) === true,
  heldContextLimit: LOCAL_HELD_CONTEXT_LIMIT,
});
await applyAgentInboxStateMachineEffects(coordinator, plan.effects);
if (typeof plan.forwardSeenUpToSeq === "number") {
  if (action === "send") body.seenUpToSeq = plan.forwardSeenUpToSeq;
}
return {
  bodyText: JSON.stringify(body),
  target,
  freshnessContextMode,
  localResponse: plan.localResponse,
};

const alreadySeenPending: AgentInboxStateMachineMessage[] = [];
const unconsumedMessages: AgentInboxStateMachineMessage[] = [];
for (const message of pending) {
  if (isMessageModelSeen(input, message)) {
    alreadySeenPending.push(message);
  } else {
    unconsumedMessages.push(message);
  }
}
appendTrace(trace, "pending_context_classified", {
  pendingCount: pending.length,
  unseenCount: unconsumedMessages.length,
});

if (unconsumedMessages.length === 0) {
  const contiguousBoundary = maxKnownContiguousBoundary(input);
  const canAdvanceBoundary = typeof contiguousBoundary === "number" && contiguousBoundary >= boundary.seenUpToSeq;

const heldBoundary = resolveFreshnessBoundary(unconsumedMessages);
if (heldBoundary.ok) {
  const heldMessages = latestVisibleMessages(unconsumedMessages, heldContextLimit);
  const omittedMessageCount = Math.max(0, unconsumedMessages.length - heldMessages.length);
  const context: HeldContext = {
    heldMessages,
    newMessageCount: unconsumedMessages.length,
    shownMessageCount: heldMessages.length,
    omittedMessageCount,
    seenUpToSeq: heldBoundary.seenUpToSeq,
  };

const sendFreshnessEnabled = isSendFreshnessEnabled(agent.serverId, actingAgentId);
const sendFreshnessMode = (process.env.SLOCK_ATTESTED_SEND_MODE ?? "on").trim().toLowerCase();
const shouldRunSendFreshness = sendFreshnessEnabled &&
  (requestedSendFreshness || sendFreshnessMode === "force");

export interface SavedDraft {
  content: string;
  attachmentIds: string[];
  mentions?: AgentApiStructuredMention[];
  savedAt: number;
  reholdCount: number;
  seenUpToSeq?: number;
}

const reholdCount = Number.isFinite(draft.reholdCount) ? draft.reholdCount : 0;
const seenUpToSeq = Number.isFinite(draft.seenUpToSeq) ? draft.seenUpToSeq : undefined;
if (Date.now() - savedAt > DEFAULT_LOCAL_DRAFT_TTL_MS) {
  clearSavedDraft(agentId, target);
  return null;
}

if (!contextWasWithheld && typeof data.seenUpToSeq === "number" && Number.isFinite(data.seenUpToSeq)) {
  recordConsumedSeqs(agentContext.agentId, { [target]: data.seenUpToSeq });
}
setSavedDraft(agentContext.agentId, target, {
  content: outgoingContent,
  attachmentIds: outgoingAttachmentIds,
  mentions: outgoingMentions,
  savedAt: currentTimeMs(),
  reholdCount: previousDraftReholdCount + 1,
  seenUpToSeq: contextWasWithheld ? seenUpToSeq : data.seenUpToSeq,
});

throw cliError(
  "SEND_HELD_AS_DRAFT",
  "Message held as draft; no target delivery occurred.",
  {
    draftSaved: true,
    effect: "draft_saved",
    // The held text above already states the effect and lists both recovery
    // commands verbatim, so the labelled restatements are dropped from TEXT
    // only. Every field is kept, so JSON is unchanged (task #264).
    textDetailMode: "omit_restated_lines",
    retryable: false,
    outputMode: opts.json ? "json" : "text",
    details: { held: heldDetails as unknown as Record<string, unknown> },
    suggestedNextAction: "Review the held context, then update the draft or send the current draft unchanged.",
  },
);

const readState = await channelService.markRead(
  { kind: "agent", id: actingAgentId },
  resolved.channelId,
  latestSeq,
);

assert.equal(held.status, 200);
assert.equal(held.body.state, "held");
assert.equal(held.body.newMessageCount, 5);
assert.equal(held.body.shownMessageCount, 3);
assert.equal(held.body.omittedMessageCount, 2);
assert.deepEqual(
  held.body.heldMessages.map((message: { content: string }) => message.content),
  ["unread-3", "unread-4", "unread-5"],
);
assert.deepEqual(acknowledged, [
  { agentId: fixture.agentId, channelId: fixture.channelId, maxSeq: unreadMessages[4]!.seq },
]);

function canonicalRevisionCas(row: TaskRow) {
  return and(eq(tasks.id, row.id), eq(tasks.revision, row.revision));
}

const [updated] = await executor
  .update(tasks)
  .set({
    status: nextStatus,
    claimedByType,
    claimedById,
    // Monotonic ownership epoch, same rule as the message path: a resumed
    // task must advance `claimedAt` even when the wall clock repeats a
    // millisecond, or the CAS below cannot tell two claims apart.
    claimedAt: nextClaimedAt(observed.claimedAt),
    revision: observed.revision + 1,
    updatedAt: new Date(),
  })
  .where(and(
    canonicalRevisionCas(observed),
    canonicalClaimCasPredicate(claimedByType, claimedById),
  ))
  .returning();

if (!updated) return await canonicalClaimRaceReason(executor, observed.id, claimedByType, claimedById);
